-- Feste Einzel-SELECT-Profile der vorhandenen CLR-String-Wrapper.
DECLARE @ExpectedApiCount int=5;
INSERT @Apis VALUES
(1,N'toolbelt_string',N'TVF_ColognePhonetic','SELECT',N'SELECT * FROM toolbelt_string.TVF_ColognePhonetic(N''x'');',N'DECLARE @R table(PhoneticCode varchar(max),ErrorCode int); DELETE @R; INSERT @R SELECT PhoneticCode,ErrorCode FROM toolbelt_string.TVF_ColognePhonetic(N''x''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND CONVERT(varbinary(max),PhoneticCode)=CONVERT(varbinary(max),''48'')) THROW 52097,N''CLR string Cologne oracle.'',12; DELETE @R; INSERT @R SELECT PhoneticCode,ErrorCode FROM toolbelt_string.TVF_ColognePhonetic(N''ax''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND CONVERT(varbinary(max),PhoneticCode)=CONVERT(varbinary(max),''048'')) THROW 52097,N''CLR string Cologne oracle.'',12; DELETE @R; INSERT @R SELECT PhoneticCode,ErrorCode FROM toolbelt_string.TVF_ColognePhonetic(N''''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND CONVERT(varbinary(max),PhoneticCode)=CONVERT(varbinary(max),'''')) THROW 52097,N''CLR string Cologne oracle.'',12; DELETE @R; INSERT @R SELECT PhoneticCode,ErrorCode FROM toolbelt_string.TVF_ColognePhonetic(NULL); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND PhoneticCode IS NULL) THROW 52097,N''CLR string Cologne NULL oracle.'',12;'),
(2,N'toolbelt_string',N'TVF_DoubleMetaphone','SELECT',N'SELECT * FROM toolbelt_string.TVF_DoubleMetaphone(N''the'');',N'DECLARE @R table(PrimaryCode varchar(max),AlternateCode varchar(max),ErrorCode int); DELETE @R; INSERT @R SELECT PrimaryCode,AlternateCode,ErrorCode FROM toolbelt_string.TVF_DoubleMetaphone(N''the''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND CONVERT(varbinary(max),PrimaryCode)=CONVERT(varbinary(max),''0'') AND CONVERT(varbinary(max),AlternateCode)=CONVERT(varbinary(max),''T'')) THROW 52097,N''CLR string Double oracle.'',12; DELETE @R; INSERT @R SELECT PrimaryCode,AlternateCode,ErrorCode FROM toolbelt_string.TVF_DoubleMetaphone(N''AJ''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND CONVERT(varbinary(max),PrimaryCode)=CONVERT(varbinary(max),''AJ'') AND CONVERT(varbinary(max),AlternateCode)=CONVERT(varbinary(max),''A '')) THROW 52097,N''CLR string Double oracle.'',12; DELETE @R; INSERT @R SELECT PrimaryCode,AlternateCode,ErrorCode FROM toolbelt_string.TVF_DoubleMetaphone(N''''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND CONVERT(varbinary(max),PrimaryCode)=CONVERT(varbinary(max),'''') AND CONVERT(varbinary(max),AlternateCode)=CONVERT(varbinary(max),'''')) THROW 52097,N''CLR string Double oracle.'',12; DELETE @R; INSERT @R SELECT PrimaryCode,AlternateCode,ErrorCode FROM toolbelt_string.TVF_DoubleMetaphone(NULL); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND PrimaryCode IS NULL AND AlternateCode IS NULL) THROW 52097,N''CLR string Double NULL oracle.'',12;'),
(3,N'toolbelt_string',N'TVF_LevenshteinDistance','SELECT',N'SELECT * FROM toolbelt_string.TVF_LevenshteinDistance(N''CA'',N''AC'',NULL,N''standard'');',N'DECLARE @R table(Distance int,ExceedsMaxDistance bit,ErrorCode int); DELETE @R; INSERT @R SELECT Distance,ExceedsMaxDistance,ErrorCode FROM toolbelt_string.TVF_LevenshteinDistance(N''kitten'',N''sitting'',NULL,N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE Distance=3 AND ExceedsMaxDistance=0 AND ErrorCode=0) THROW 52097,N''CLR string distance oracle.'',12; DELETE @R; INSERT @R SELECT Distance,ExceedsMaxDistance,ErrorCode FROM toolbelt_string.TVF_LevenshteinDistance(N''CA'',N''AC'',NULL,N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE Distance=2 AND ExceedsMaxDistance=0 AND ErrorCode=0) THROW 52097,N''CLR string distance oracle.'',12; DELETE @R; INSERT @R SELECT Distance,ExceedsMaxDistance,ErrorCode FROM toolbelt_string.TVF_LevenshteinDistance(N''a'',N''bbb'',1,N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE Distance IS NULL AND ExceedsMaxDistance=1 AND ErrorCode=0) THROW 52097,N''CLR string distance oracle.'',12; DELETE @R; INSERT @R SELECT Distance,ExceedsMaxDistance,ErrorCode FROM toolbelt_string.TVF_LevenshteinDistance(NULL,N''x'',-1,N''invalid''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE Distance IS NULL AND ExceedsMaxDistance IS NULL AND ErrorCode=0) THROW 52097,N''CLR string distance oracle.'',12; '),
(4,N'toolbelt_string',N'TVF_OsaDistance','SELECT',N'SELECT * FROM toolbelt_string.TVF_OsaDistance(N''CA'',N''AC'',NULL,N''standard'');',N'DECLARE @R table(Distance int,ExceedsMaxDistance bit,ErrorCode int); DELETE @R; INSERT @R SELECT Distance,ExceedsMaxDistance,ErrorCode FROM toolbelt_string.TVF_OsaDistance(N''kitten'',N''sitting'',NULL,N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE Distance=3 AND ExceedsMaxDistance=0 AND ErrorCode=0) THROW 52097,N''CLR string distance oracle.'',12; DELETE @R; INSERT @R SELECT Distance,ExceedsMaxDistance,ErrorCode FROM toolbelt_string.TVF_OsaDistance(N''CA'',N''AC'',NULL,N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE Distance=1 AND ExceedsMaxDistance=0 AND ErrorCode=0) THROW 52097,N''CLR string distance oracle.'',12; DELETE @R; INSERT @R SELECT Distance,ExceedsMaxDistance,ErrorCode FROM toolbelt_string.TVF_OsaDistance(N''a'',N''bbb'',1,N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE Distance IS NULL AND ExceedsMaxDistance=1 AND ErrorCode=0) THROW 52097,N''CLR string distance oracle.'',12; DELETE @R; INSERT @R SELECT Distance,ExceedsMaxDistance,ErrorCode FROM toolbelt_string.TVF_OsaDistance(NULL,N''x'',-1,N''invalid''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE Distance IS NULL AND ExceedsMaxDistance IS NULL AND ErrorCode=0) THROW 52097,N''CLR string distance oracle.'',12; '),
(5,N'toolbelt_string',N'TVF_JaroWinklerSimilarity','SELECT',N'SELECT * FROM toolbelt_string.TVF_JaroWinklerSimilarity(N''A'',N''A'',N''standard'');',N'DECLARE @R table(Similarity float,ErrorCode int); DELETE @R; INSERT @R SELECT Similarity,ErrorCode FROM toolbelt_string.TVF_JaroWinklerSimilarity(N''A'',N''A'',N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND Similarity IS NOT NULL AND ABS(Similarity-(1))<=1e-12) THROW 52097,N''CLR string Jaro oracle.'',12; DELETE @R; INSERT @R SELECT Similarity,ErrorCode FROM toolbelt_string.TVF_JaroWinklerSimilarity(N''A'',N''a'',N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND Similarity IS NOT NULL AND ABS(Similarity-(0))<=1e-12) THROW 52097,N''CLR string Jaro oracle.'',12; DELETE @R; INSERT @R SELECT Similarity,ErrorCode FROM toolbelt_string.TVF_JaroWinklerSimilarity(N''ABC'',N''ACB'',N''standard''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND Similarity IS NOT NULL AND ABS(Similarity-(CONVERT(float,5)/9))<=1e-12) THROW 52097,N''CLR string Jaro oracle.'',12; DELETE @R; INSERT @R SELECT Similarity,ErrorCode FROM toolbelt_string.TVF_JaroWinklerSimilarity(NULL,N''x'',N''invalid''); IF (SELECT COUNT(*) FROM @R)<>1 OR NOT EXISTS(SELECT 1 FROM @R WHERE ErrorCode=0 AND Similarity IS NULL) THROW 52097,N''CLR string Jaro NULL oracle.'',12;');
